
import re
from uuid import uuid4

from sqlalchemy import func
from sqlalchemy.orm import Session

from app.context_engine.models import Conversation, Message, ConversationSummary
from app.system_prompt import MAX_CUSTOM_PROMPT_LENGTH


# Conversation identifiers are UUIDs generated by this service. The
# pattern is used to reject obviously malformed ids before they reach
# the database (unknown-but-well-formed ids still return None/404).
CONVERSATION_ID_PATTERN = re.compile(
    r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"
    r"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
)


def normalize_session_id(session_id: str | None) -> str | None:
    """Return a clean session-id claim, or None when absent."""

    if session_id is None:
        return None

    cleaned = session_id.strip()

    return cleaned or None


def conversation_accessible(
    conversation: Conversation,
    session_id: str | None,
) -> bool:
    """Apply the session-ownership model to one conversation.

    The application has no authentication system, so ownership is a
    caller-supplied claim (mirroring ``Memory.user_id``):

    - A conversation without a session_id is shared (legacy behavior;
      every caller may continue it).
    - A conversation with a session_id is only accessible to callers
      presenting exactly that session_id.
    """

    if conversation.session_id is None:
        return True

    return conversation.session_id == normalize_session_id(session_id)


def is_valid_conversation_id(conversation_id: str) -> bool:
    """Report whether the id has the shape this service generates."""

    if not isinstance(conversation_id, str):
        return False

    return bool(CONVERSATION_ID_PATTERN.match(conversation_id.strip()))


def create_conversation(
    db: Session,
    title: str | None = None,
    session_id: str | None = None,
) -> Conversation:
    # Generate a unique ID for the new conversation.
    conversation_id = str(uuid4())

    # Create the conversation database record.
    conversation = Conversation(
        id=conversation_id,
        title=title,
        session_id=normalize_session_id(session_id),
    )

    # Add the record to the current database transaction.
    db.add(conversation)

    # Save the conversation to PostgreSQL.
    db.commit()

    # Refresh the object to retrieve database-generated values.
    db.refresh(conversation)

    return conversation


def get_conversation(
    db: Session,
    conversation_id: str,
) -> Conversation | None:
    """Return one conversation or None when it does not exist."""

    if not conversation_id or not conversation_id.strip():
        raise ValueError("conversation_id cannot be empty.")

    return db.get(Conversation, conversation_id.strip())


def list_conversations(
    db: Session,
    limit: int = 50,
    offset: int = 0,
    session_id: str | None = None,
) -> list[dict]:
    """List conversations, newest first, with their message counts.

    When ``session_id`` is supplied, only conversations that caller may
    access are returned (shared conversations plus conversations owned
    by that session).
    """

    # Validate the requested page before querying the database.
    if not 1 <= limit <= 200:
        raise ValueError("limit must be between 1 and 200.")

    if offset < 0:
        raise ValueError("offset cannot be negative.")

    query = db.query(Conversation)

    cleaned_session = normalize_session_id(session_id)

    if cleaned_session is not None:
        query = query.filter(
            (Conversation.session_id.is_(None))
            | (Conversation.session_id == cleaned_session)
        )

    conversations = (
        query.order_by(
            Conversation.created_at.desc(),
            Conversation.id.desc(),
        )
        .offset(offset)
        .limit(limit)
        .all()
    )

    if not conversations:
        return []

    # Count messages once for every conversation on this page.
    conversation_ids = [
        conversation.id for conversation in conversations
    ]

    message_counts = dict(
        db.query(
            Message.conversation_id,
            func.count(Message.id),
        )
        .filter(Message.conversation_id.in_(conversation_ids))
        .group_by(Message.conversation_id)
        .all()
    )

    return [
        {
            "id": conversation.id,
            "title": conversation.title,
            "session_id": conversation.session_id,
            "created_at": (
                conversation.created_at.isoformat()
                if conversation.created_at
                else None
            ),
            "message_count": message_counts.get(
                conversation.id,
                0,
            ),
        }
        for conversation in conversations
    ]


def save_message(
    db: Session,
    conversation_id: str,
    role: str,
    content: str,
) -> Message:
    # Allow only the roles supported by our chat application.
    if role not in {"user", "assistant"}:
        raise ValueError(
            "Role must be 'user' or 'assistant'."
        )

    # Reject messages that contain no meaningful content.
    if not content.strip():
        raise ValueError("Message content cannot be empty.")

    # Verify that the conversation exists before saving.
    conversation = db.get(Conversation, conversation_id)

    if conversation is None:
        raise ValueError("Conversation not found.")

    # Create a message linked to the selected conversation.
    message = Message(
        conversation_id=conversation_id,
        role=role,
        content=content,
    )

    # Add the message to the database transaction.
    db.add(message)

    # Persist the message in PostgreSQL.
    db.commit()

    # Retrieve generated fields such as the message ID.
    db.refresh(message)

    return message


def get_last_n_messages(
    db: Session,
    conversation_id: str,
    n: int = 6,
) -> list[dict]:
    # Ensure the requested number of messages is valid.
    if n < 1:
        raise ValueError("n must be at least 1.")

    # Fetch the newest N messages first.
    # Descending IDs mean the most recently inserted messages
    # are selected before older messages.
    messages = (
        db.query(Message)
        .filter(
            Message.conversation_id == conversation_id
        )
        .order_by(Message.id.desc())
        .limit(n)
        .all()
    )

    # Reverse the selected messages into chronological order.
    messages.reverse()

    # Return plain dictionaries for the Context Engine.
    return [
        _serialize_message(message)
        for message in messages
    ]


def list_conversation_messages(
    db: Session,
    conversation_id: str,
    limit: int = 50,
    chronological: bool = True,
) -> list[dict]:
    """Return one conversation's messages.

    ``chronological=True`` returns the earliest messages first (the
    natural reading order of a transcript); ``False`` returns the most
    recent messages first, matching the pre-existing endpoint contract.
    """

    if not 1 <= limit <= 200:
        raise ValueError("limit must be between 1 and 200.")

    query = (
        db.query(Message)
        .filter(Message.conversation_id == conversation_id)
    )

    if chronological:
        messages = (
            query.order_by(Message.id.asc()).limit(limit).all()
        )
    else:
        # Most recent first, then reversed into reading order.
        messages = (
            query.order_by(Message.id.desc()).limit(limit).all()
        )
        messages.reverse()

    return [
        _serialize_message(message)
        for message in messages
    ]


def _serialize_message(message: Message) -> dict:
    return {
        "id": message.id,
        "conversation_id": message.conversation_id,
        "role": message.role,
        "content": message.content,
        "created_at": message.created_at.isoformat(),
    }


def clear_conversation(
    db: Session,
    conversation_id: str,
) -> dict:
    """Delete one conversation's messages and stored summary.

    The conversation itself is kept, so its identifier stays valid for
    continued chats. Summaries are removed explicitly because the ORM
    relationship for them is not mapped (database-level ON DELETE
    CASCADE covers PostgreSQL, but the explicit delete keeps this
    portable and transactional).
    """

    conversation = db.get(Conversation, conversation_id)

    if conversation is None:
        return {"cleared": False, "messages_deleted": 0}

    messages_deleted = (
        db.query(Message)
        .filter(Message.conversation_id == conversation_id)
        .delete(synchronize_session=False)
    )

    summaries_deleted = (
        db.query(ConversationSummary)
        .filter(
            ConversationSummary.conversation_id
            == conversation_id
        )
        .delete(synchronize_session=False)
    )

    db.commit()

    return {
        "cleared": True,
        "messages_deleted": messages_deleted,
        "summaries_deleted": summaries_deleted,
    }


def delete_conversation(
    db: Session,
    conversation_id: str,
) -> dict:
    """Delete one conversation with its messages and summary."""

    conversation = db.get(Conversation, conversation_id)

    if conversation is None:
        return {"deleted": False, "messages_deleted": 0}

    messages_deleted = (
        db.query(Message)
        .filter(Message.conversation_id == conversation_id)
        .delete(synchronize_session=False)
    )

    (
        db.query(ConversationSummary)
        .filter(
            ConversationSummary.conversation_id
            == conversation_id
        )
        .delete(synchronize_session=False)
    )

    db.delete(conversation)
    db.commit()

    return {
        "deleted": True,
        "messages_deleted": messages_deleted,
    }


def get_conversation_system_prompt(
    db: Session,
    conversation_id: str,
) -> dict:
    """Return one conversation's custom system-prompt settings.

    Raises ValueError when the conversation does not exist, so the
    API layer can translate it into a client error.
    """

    conversation = db.get(Conversation, conversation_id.strip())

    if conversation is None:
        raise ValueError("Conversation not found.")

    custom_prompt = conversation.system_prompt or ""

    return {
        "conversation_id": conversation.id,
        "custom_prompt": custom_prompt,
        "using_default": not custom_prompt.strip(),
    }


def save_conversation_system_prompt(
    db: Session,
    conversation_id: str,
    custom_prompt: str,
) -> dict:
    """Persist (or clear) one conversation's custom system prompt.

    An empty prompt resets the conversation to the default system
    instructions. Only this conversation's row is touched; every other
    conversation keeps its own prompt. Raises ValueError for unknown
    conversations and for prompts that are too long.
    """

    if custom_prompt is None:
        custom_prompt = ""

    if not isinstance(custom_prompt, str):
        raise ValueError("custom_prompt must be a string.")

    cleaned = custom_prompt.strip()

    if len(cleaned) > MAX_CUSTOM_PROMPT_LENGTH:
        raise ValueError(
            "custom_prompt must be at most "
            f"{MAX_CUSTOM_PROMPT_LENGTH} characters."
        )

    conversation = db.get(Conversation, conversation_id.strip())

    if conversation is None:
        raise ValueError("Conversation not found.")

    # NULL means "no custom prompt": the conversation returns to the
    # default system instructions.
    conversation.system_prompt = cleaned or None

    db.commit()
    db.refresh(conversation)

    return {
        "conversation_id": conversation.id,
        "custom_prompt": conversation.system_prompt or "",
        "using_default": not (conversation.system_prompt or "").strip(),
    }


def reset_conversation_system_prompt(
    db: Session,
    conversation_id: str,
) -> dict:
    """Delete one conversation's custom prompt (default instructions).

    Other conversations' prompts are unaffected.
    """

    return save_conversation_system_prompt(
        db=db,
        conversation_id=conversation_id,
        custom_prompt="",
    )


def get_conversation_message_window(
    db: Session,
    conversation_id: str,
    n: int = 6,
) -> dict:
    """
    Separate a conversation into older messages
    and the latest N recent messages.
    """

    # Reject invalid window sizes.
    if n < 1:
        raise ValueError("n must be at least 1.")

    # Verify that the requested conversation exists.
    conversation = db.get(Conversation, conversation_id)

    if conversation is None:
        raise ValueError("Conversation not found.")

    # Load messages in chronological order.
    all_messages = (
        db.query(Message)
        .filter(Message.conversation_id == conversation_id)
        .order_by(Message.id.asc())
        .all()
    )

    # Split at the boundary between older and recent messages.
    split_index = max(0, len(all_messages) - n)

    older_messages = all_messages[:split_index]
    recent_messages = all_messages[split_index:]

    # Return both groups without changing stored messages.
    return {
        "conversation_id": conversation_id,
        "total_messages": len(all_messages),
        "recent_count": len(recent_messages),
        "older_count": len(older_messages),
        "older_messages": [
            _serialize_message(message)
            for message in older_messages
        ],
        "recent_messages": [
            _serialize_message(message)
            for message in recent_messages
        ],
    }
